using System;
using System.Collections.Generic;
using Framework.AI.Decision;
using Game.AI.Actions;
using Game.AI.Core;
using Game.AI.Parameters;
using Game.AI.Perception;
using Game.AI.Spatial;
using Game.AI.Tactics;
using UnityEngine;

namespace Game.AI.Decision
{
    /// <summary>
    /// 敵AIの性格と状況に応じて行動を評価する。
    /// </summary>
    /// <remarks>
    /// 行動候補の生成とUtility評価を担当する。
    /// 実際の行動開始や移動処理は行わない。
    /// </remarks>
    public sealed class MazeEnemyUtility
    {
        /// <summary>
        /// 敵AIの基本コンテキスト。
        /// </summary>
        private readonly MazeEnemyContext enemy;

        /// <summary>
        /// 行動実行用コンテキスト。
        /// </summary>
        private readonly MazeEnemyActionContext actions;

        /// <summary>
        /// 対象の認識情報を管理するシステム。
        /// </summary>
        private readonly MazeEnemyPerceptionController perception;

        /// <summary>
        /// 縄張りの評価システム。
        /// </summary>
        private readonly MazeEnemyTerritory territory;

        /// <summary>
        /// 巡回と探索の評価システム。
        /// </summary>
        private readonly MazeEnemySpatialEvaluator spatial;

        /// <summary>
        /// 追跡と逃走などの戦術評価システム。
        /// </summary>
        private readonly MazeEnemyTacticalEvaluator tactical;

        /// <summary>
        /// 行動候補の評価結果。
        /// </summary>
        private readonly Dictionary<
            MazeEnemyActionType,
            MazeEnemyUtilityCandidate> candidates =
                new Dictionary<
                    MazeEnemyActionType,
                    MazeEnemyUtilityCandidate>();

        /// <summary>
        /// 汎用Utility AIによる行動選択システム。
        /// </summary>
        private readonly UtilitySelector<
            MazeEnemyActionType,
            MazeEnemyUtility> selector;


        /// <summary>
        /// 視界喪失直後の追跡猶予時間。単位は秒。
        /// </summary>
        private const float TrackingGraceDuration = 1.5f;

        /// <summary>
        /// 視界喪失後の最大予測距離。単位はセル。
        /// </summary>
        private const int MaxTrackingPredictionDistance = 4;

        /// <summary>
        /// 現在の行動候補数。
        /// </summary>
        public int CandidateCount =>
            candidates.Count;

        /// <summary>
        /// 最後に実行したUtility評価の結果。
        /// </summary>
        public IReadOnlyList<
            UtilityEvaluation<MazeEnemyActionType>>
            LastEvaluations =>
                selector.LastEvaluations;

        /// <summary>
        /// 利用可能な状態であるか。
        /// </summary>
        public bool IsValid =>
            enemy.IsValid &&
            actions.IsValid &&
            perception.IsValid &&
            territory.IsValid &&
            spatial.IsValid &&
            tactical.IsValid;

        /// <summary>
        /// 敵AIの行動評価システムを生成する。
        /// </summary>
        /// <param name="enemy">敵AIコンテキスト</param>
        /// <param name="actions">行動コンテキスト</param>
        /// <param name="perception">認識システム</param>
        /// <param name="territory">縄張り評価</param>
        /// <param name="spatial">空間評価</param>
        /// <param name="tactical">戦術評価</param>
        public MazeEnemyUtility(
            MazeEnemyContext enemy,
            MazeEnemyActionContext actions,
            MazeEnemyPerceptionController perception,
            MazeEnemyTerritory territory,
            MazeEnemySpatialEvaluator spatial,
            MazeEnemyTacticalEvaluator tactical)
        {
            this.enemy = enemy ??
                throw new ArgumentNullException(nameof(enemy));

            this.actions = actions ??
                throw new ArgumentNullException(nameof(actions));

            this.perception = perception ??
                throw new ArgumentNullException(nameof(perception));

            this.territory = territory ??
                throw new ArgumentNullException(nameof(territory));

            this.spatial = spatial ??
                throw new ArgumentNullException(nameof(spatial));

            this.tactical = tactical ??
                throw new ArgumentNullException(nameof(tactical));

            // 異なる敵の評価システムを混在させない。
            if (!ReferenceEquals(actions.Enemy, enemy) ||
                !ReferenceEquals(perception.Context, enemy) ||
                !ReferenceEquals(territory.Context, enemy) ||
                !ReferenceEquals(spatial.Context, enemy) ||
                !ReferenceEquals(spatial.Territory, territory) ||
                !ReferenceEquals(tactical.Context, enemy))
            {
                throw new ArgumentException(
                    "敵AIコンテキストが一致していません。");
            }

            if (!IsValid)
            {
                throw new ArgumentException(
                    "行動評価の依存関係が無効です。");
            }

            selector =
                new UtilitySelector<
                    MazeEnemyActionType,
                    MazeEnemyUtility>(0.08f);

            RegisterOption(MazeEnemyActionType.Idle);
            RegisterOption(MazeEnemyActionType.Patrol);
            RegisterOption(MazeEnemyActionType.Explore);
            RegisterOption(MazeEnemyActionType.Chase);
            RegisterOption(MazeEnemyActionType.Intercept);
            RegisterOption(MazeEnemyActionType.Escape);
            RegisterOption(
                MazeEnemyActionType.ReturnToTerritory);
        }

        /// <summary>
        /// Utility AIへ行動の評価定義を登録する。
        /// </summary>
        /// <param name="action">登録する行動</param>
        private void RegisterOption(
            MazeEnemyActionType action)
        {
            var consideration =
                new UtilityConsideration<MazeEnemyUtility>(
                    action.ToString(),
                    utility => utility.GetScore(action));

            var option =
                new UtilityOption<
                    MazeEnemyActionType,
                    MazeEnemyUtility>(
                        action,
                        new[] { consideration },
                        weight: 1f,
                        useCompensation: false,
                        availability: utility =>
                            utility.candidates.ContainsKey(
                                action));

            selector.TryAddOption(option);
        }

        /// <summary>
        /// 指定された行動の評価値を取得する。
        /// </summary>
        /// <param name="action">行動の種類</param>
        /// <returns>行動の評価値</returns>
        public float GetScore(
            MazeEnemyActionType action)
        {
            return candidates.TryGetValue(
                action, out var candidate)
                    ? candidate.Score
                    : 0f;
        }

        /// <summary>
        /// 指定された行動候補を取得する。
        /// </summary>
        /// <param name="action">行動の種類</param>
        /// <param name="candidate">行動候補</param>
        /// <returns>取得できた場合はtrue</returns>
        public bool TryGetCandidate(
            MazeEnemyActionType action,
            out MazeEnemyUtilityCandidate candidate)
        {
            return candidates.TryGetValue(
                action, out candidate);
        }

        /// <summary>
        /// 現在の状況から行動候補を生成する。
        /// </summary>
        /// <param name="currentAction">現在の行動</param>
        /// <returns>評価できた場合はtrue</returns>
        public bool Evaluate(
            MazeEnemyActionType currentAction)
        {
            candidates.Clear();

            if (!IsValid || !enemy.CanAct)
            {
                return false;
            }

            // 他の行動が存在しない場合の待機候補。
            candidates[MazeEnemyActionType.Idle] =
                new MazeEnemyUtilityCandidate(
                    MazeEnemyActionType.Idle,
                    default,
                    false,
                    0.02f);

            EvaluateRoutine(
                MazeEnemyActionType.Patrol,
                MazeEnemySpatialMode.Patrol,
                currentAction);

            EvaluateRoutine(
                MazeEnemyActionType.Explore,
                MazeEnemySpatialMode.Exploration,
                currentAction);

            EvaluatePlayer();
            EvaluateThreat();
            EvaluateTerritoryReturn();

            return true;
        }

        /// <summary>
        /// 最も適切な行動候補を選択する。
        /// </summary>
        /// <param name="currentAction">現在の行動</param>
        /// <param name="candidate">選択された行動候補</param>
        /// <returns>選択できた場合はtrue</returns>
        public bool TrySelect(
            MazeEnemyActionType currentAction,
            out MazeEnemyUtilityCandidate candidate)
        {
            candidate = default;

            if (!IsValid || !enemy.CanAct)
            {
                return false;
            }

            // 待機に継続ボーナスを付与しない。
            MazeEnemyActionType continuationAction =
                currentAction == MazeEnemyActionType.Idle
                    ? MazeEnemyActionType.None
                    : currentAction;

            if (!selector.TrySelect(
                    this,
                    continuationAction,
                    out var evaluation))
            {
                return false;
            }

            return candidates.TryGetValue(
                evaluation.ActionId,
                out candidate);
        }

        /// <summary>
        /// 巡回または探索行動を評価する。
        /// </summary>
        /// <param name="action">行動の種類</param>
        /// <param name="mode">空間評価モード</param>
        /// <param name="currentAction">現在の行動</param>
        private void EvaluateRoutine(
            MazeEnemyActionType action,
            MazeEnemySpatialMode mode,
            MazeEnemyActionType currentAction)
        {
            if (actions.GetMoveSpeed(action) <= 0f)
            {
                return;
            }

            float preference = GetParameter(
                action == MazeEnemyActionType.Patrol
                    ? MazeEnemyParameter.PatrolPreference
                    : MazeEnemyParameter.Exploration);

            // 嗜好が0でも基本的な移動行動は許可する。
            float weight = 0.2f + preference * 0.6f;

            // 実行中の巡回先・探索先を維持する。
            if (currentAction == action &&
                actions.PathFollower.IsFollowing &&
                actions.TryGetDestination(
                    action, out Vector2Int currentDestination) &&
                enemy.IsWalkable(currentDestination))
            {
                float score;

                if (spatial.TryEvaluate(
                    currentDestination,
                    mode,
                    out var currentEvaluation))
                {
                    score = currentEvaluation.Score * weight;
                }
                else
                {
                    // 最後の移動区間では探索起点と
                    // 目的地が一致するため評価を維持する。
                    score = 0.2f * weight;
                }

                AddMoveCandidate(
                    action,
                    currentDestination,
                    score);

                return;
            }

            if (spatial.TrySelectBestPosition(
                    mode,
                    out var evaluation,
                    minDistance: 2,
                    maxDistance: 8))
            {
                AddMoveCandidate(
                    action,
                    evaluation.Position,
                    evaluation.Score * weight);

                return;
            }

            // 狭い領域でも隣接セルへの移動を許可する。
            if (spatial.TrySelectBestPosition(
                    mode,
                    out evaluation,
                    minDistance: 1,
                    maxDistance: 8))
            {
                AddMoveCandidate(
                    action,
                    evaluation.Position,
                    evaluation.Score * weight);
            }
        }

        /// <summary>
        /// プレイヤーへの追跡と迎撃を評価する。
        /// </summary>
        /// <remarks>
        /// 視界喪失直後は最終認識情報を利用して追跡を継続する。
        /// 対象の実際の現在位置は参照しない。
        /// </remarks>
        private void EvaluatePlayer()
        {
            if (!perception.TryGetBestObservation(
                    MazeEnemyTargetType.Player,
                    out var target))
            {
                return;
            }

            float aggression = GetParameter(
                MazeEnemyParameter.Aggression);

            float persistence = GetParameter(
                MazeEnemyParameter.Persistence);

            float aggressionWeight =
                0.25f + aggression * 0.75f;

            // 視界から外れた対象は記憶に基づいて追跡する。
            if (target.IsRemembered)
            {
                EvaluateRememberedPlayer(
                    target,
                    aggressionWeight,
                    persistence);

                return;
            }

            // 視認中の対象への通常追跡を評価する。
            if (tactical.TryEvaluateChase(
                    target, out var chase) &&
                chase.Distance > 0)
            {
                float territoryWeight =
                    territory.GetPreferenceMultiplier(
                        chase.Destination);

                float score =
                    chase.Score *
                    aggressionWeight *
                    territoryWeight;

                AddMoveCandidate(
                    MazeEnemyActionType.Chase,
                    chase.Destination,
                    score);
            }

            // 視認中の対象への迎撃を評価する。
            if (tactical.TryEvaluateIntercept(
                    target, out var intercept))
            {
                float territoryWeight =
                    territory.GetPreferenceMultiplier(
                        intercept.Destination);

                float score =
                    intercept.Score *
                    aggressionWeight *
                    territoryWeight;

                AddMoveCandidate(
                    MazeEnemyActionType.Intercept,
                    intercept.Destination,
                    score);
            }
        }

        /// <summary>
        /// 記憶しているプレイヤーへの追跡を評価する。
        /// </summary>
        /// <param name="target">対象の最終認識情報</param>
        /// <param name="aggressionWeight">攻撃性による評価補正</param>
        /// <param name="persistence">執着性</param>
        private void EvaluateRememberedPlayer(
            MazeEnemyTargetObservation target,
            float aggressionWeight,
            float persistence)
        {
            // 最後に対象を視認してからの経過時間。
            float elapsedTime = (float)Math.Max(
                0d,
                enemy.CurrentTime - target.LastSeenTime);

            // 執着性に応じて追跡猶予時間を変化させる。
            float graceDuration =
                TrackingGraceDuration *
                (0.5f + persistence);

            bool isTrackingGrace =
                elapsedTime <= graceDuration;

            // 最終認識情報から追跡先を決定する。
            Vector2Int destination =
                GetTrackingDestination(target);

            // 移動中は次に到達するセルを探索起点とする。
            Vector2Int origin = tactical.Origin;

            if (destination == origin)
            {
                // 最後の移動区間では目的地を維持する。
                if (!enemy.IsTraversing ||
                    !actions.PathFollower.IsFollowing ||
                    !actions.TryGetDestination(
                        MazeEnemyActionType.Chase,
                        out var currentDestination) ||
                    currentDestination != destination)
                {
                    return;
                }
            }

            // 猶予時間中は記憶の信頼度低下を評価に反映しない。
            float confidence = isTrackingGrace
                ? 1f
                : target.Confidence;

            // 猶予時間終了後は執着性によって追跡を補正する。
            float persistenceWeight = isTrackingGrace
                ? 1f
                : 0.25f + persistence * 0.75f;

            float territoryWeight =
                territory.GetPreferenceMultiplier(
                    destination);

            // 記憶追跡中は距離による過度な評価低下を抑える。
            float score =
                confidence *
                aggressionWeight *
                persistenceWeight *
                territoryWeight *
                (0.7f + persistence * 0.3f);

            AddMoveCandidate(
                MazeEnemyActionType.Chase,
                destination,
                score);
        }

        /// <summary>
        /// 対象の最終認識情報から追跡先を推測する。
        /// </summary>
        /// <param name="target">対象の最終認識情報</param>
        /// <returns>推測した追跡先のセル座標</returns>
        /// <remarks>
        /// 最終認識方向へ直線的に予測する。
        /// 壁や通行不能セルを越えて予測することはない。
        /// </remarks>
        private Vector2Int GetTrackingDestination(
            MazeEnemyTargetObservation target)
        {
            Vector2Int position =
                target.LastKnownPosition;

            Vector2Int direction =
                target.LastKnownDirection;

            // 有効な上下左右方向が不明な場合は予測しない。
            if (Mathf.Abs(direction.x) +
                Mathf.Abs(direction.y) != 1)
            {
                return position;
            }

            float intelligence = GetParameter(
                MazeEnemyParameter.TacticalIntelligence);

            float predictionTime = GetParameter(
                MazeEnemyParameter.PredictionTime);

            // 戦術知能が高いほど先の位置まで予測する。
            float predictionDistance =
                target.LastKnownMoveSpeed *
                predictionTime *
                (0.5f + intelligence * 0.5f);

            int predictionSteps = Mathf.Clamp(
                Mathf.CeilToInt(predictionDistance),
                0,
                MaxTrackingPredictionDistance);

            for (int i = 0; i < predictionSteps; i++)
            {
                Vector2Int nextPosition =
                    position + direction;

                // 壁に到達した場合は予測を終了する。
                if (!enemy.IsWalkable(nextPosition))
                {
                    break;
                }

                position = nextPosition;
            }

            return position;
        }

        /// <summary>
        /// 脅威からの逃走行動を評価する。
        /// </summary>
        private void EvaluateThreat()
        {
            if (!perception.TryGetBestObservation(
                    MazeEnemyTargetType.Threat,
                    out var threat))
            {
                return;
            }

            if (!tactical.TryEvaluateEscape(
                    threat,
                    maxTravelDistance: 6,
                    out var escape))
            {
                return;
            }

            float caution = GetParameter(
                MazeEnemyParameter.Caution);

            float cautionWeight =
                0.4f + caution * 0.6f;

            float distance = Vector2Int.Distance(
                enemy.CurrentCell,
                threat.LastKnownPosition);

            // 脅威が近いほど逃走の優先度を上げる。
            float urgency =
                1f / (1f + distance * 0.15f);

            float score =
                escape.Score *
                cautionWeight *
                (0.5f + urgency * 0.5f);

            // 逃走時は縄張りによる移動制限を適用しない。
            AddMoveCandidate(
                MazeEnemyActionType.Escape,
                escape.Destination,
                score);
        }

        /// <summary>
        /// 縄張りへの帰還行動を評価する。
        /// </summary>
        private void EvaluateTerritoryReturn()
        {
            if (tactical.TryEvaluateReturn(
                out var evaluation))
            {
                AddMoveCandidate(
                    MazeEnemyActionType.ReturnToTerritory,
                    evaluation.Destination,
                    evaluation.Score);
            }
        }

        /// <summary>
        /// 移動行動の候補を登録する。
        /// </summary>
        /// <param name="action">行動の種類</param>
        /// <param name="destination">目的地</param>
        /// <param name="score">評価値</param>
        private void AddMoveCandidate(
            MazeEnemyActionType action,
            Vector2Int destination,
            float score)
        {
            if (!enemy.IsWalkable(destination) ||
                actions.GetMoveSpeed(action) <= 0f)
            {
                return;
            }

            var candidate =
                new MazeEnemyUtilityCandidate(
                    action,
                    destination,
                    true,
                    score);

            if (candidate.IsValid)
            {
                candidates[action] = candidate;
            }
        }

        /// <summary>
        /// 性格パラメーターの値を取得する。
        /// </summary>
        /// <param name="parameter">パラメーター識別子</param>
        /// <returns>パラメーター値</returns>
        private float GetParameter(
            MazeEnemyParameter parameter)
        {
            return enemy.GetParameterValue(parameter);
        }

        /// <summary>
        /// 現在の行動候補を削除する。
        /// </summary>
        public void Clear()
        {
            candidates.Clear();
        }
    }
}
